1	/**
2	 * RBAC primitives: types + pure permission checker.
3	 *
4	 * The hook form (`useCan`) lives in `src/auth/AuthProvider.tsx` because
5	 * it depends on the live session. This file stays React-free so it can
6	 * be used from non-component code (db helpers, sync workers, tests).
7	 */
8	
9	// Permissions are namespaced strings: `<module>.<verb>` or
10	// `<module>.<resource>.<verb>`. Keep them short; resolve against a real
11	// policy engine later.
12	export type Permission = string;
13	
14	export type Role = 'guard' | 'supervisor' | 'manager' | 'admin';
15	
16	export type Principal = {
17	  userId: string;
18	  roles: Role[];
19	  permissions: Permission[];
20	};
21	
22	// Stand-in for the not-yet-authenticated user. Holds zero permissions
23	// so any gated UI hides until the real session loads.
24	export const ANONYMOUS_PRINCIPAL: Principal = {
25	  userId: 'anon',
26	  roles: [],
27	  permissions: [],
28	};
29	
30	export function can(principal: Principal, permission: Permission): boolean {
31	  if (principal.permissions.includes('*')) return true;
32	  return principal.permissions.includes(permission);
