/**
 * RBAC primitives: types + pure permission checker.
 *
 * The hook form (`useCan`) lives in `src/auth/AuthProvider.tsx` because
 * it depends on the live session. This file stays React-free so it can
 * be used from non-component code (db helpers, sync workers, tests).
 */

// Permissions are namespaced strings: `<module>.<verb>` or
// `<module>.<resource>.<verb>`. Keep them short; resolve against a real
// policy engine later.
export type Permission = string;

export type Role = 'guard' | 'supervisor' | 'manager' | 'admin';

export type Principal = {
  userId: string;
  roles: Role[];
  permissions: Permission[];
};

// Stand-in for the not-yet-authenticated user. Holds zero permissions
// so any gated UI hides until the real session loads.
export const ANONYMOUS_PRINCIPAL: Principal = {
  userId: 'anon',
  roles: [],
  permissions: [],
};

export function can(principal: Principal, permission: Permission): boolean {
  if (principal.permissions.includes('*')) return true;
  return principal.permissions.includes(permission);
}

content.content:
1	/**
2	 * Gate state machine — the brain of the tablet.
3	 *
4	 * Owns:
5	 *  - camera lifecycle (active only while detecting/captured)
6	 *  - MediaPipe detect loop
7	 *  - ONNX embedding generation
8	 *  - online/offline routing (server match vs local fallback)
9	 *  - liveness challenge flow when the server asks for it
10	 *  - punch result UI state
11	 *  - outbox flush on reconnect + heartbeat-driven gallery refresh
12	 *
13	 * Server is source-of-truth. The tablet posts an embedding and
14	 * accepts whatever outcome the server returns. Offline events are
15	 * queued and re-verified against the server's current gallery on
16	 * reconnect.
17	 */
18	
19	import { useCallback, useEffect, useReducer, useRef } from "react";
20	
21	import {
22	  fetchGallery,
23	  flushOfflineBatch,
24	  heartbeat,
25	  postFaceEvent,
26	  type FaceEventResponse,
27	  type GateOutcome,
28	  type ServerConfig,
29	} from "../api/attendance";
30	import {
31	  getCachedGallery,
32	  getCachedVersion,
33	  getGallerySize,
34	  replaceGallery,
35	} from "../db/gallery";
36	import {
37	  enqueuePunch,
38	  listPending,
39	  markFailed,
40	  markSynced,
41	} from "../db/outbox";
42	import {
43	  analyzeResult,
44	  cropFace,
45	  getFaceLandmarker,
46	} from "./lib/faceLandmarker";
47	import { cosineSim, embed } from "./lib/embedder";
48	
49	const DETECT_DWELL_MS = 350;
50	const RESULT_LINGER_MS = 2400;
51	
52	export type GateState =
53	  | { kind: "boot" }
54	  | { kind: "idle"; lastSyncAt: string | null; gallerySize: number }
55	  | { kind: "loading_camera" }
56	  | { kind: "detecting" }
57	  | { kind: "matching"; mode: "server" | "local" }
58	  | { kind: "challenging"; eventId: string; poses: string[]; poseIndex: number }
59	  | { kind: "result"; outcome: GateOutcome; staffName: string | null; direction: "in" | "out" | null; offline: boolean }
60	  | { kind: "error"; message: string };
61	
62	type Action =
63	  | { type: "boot_complete"; cachedVersion: string | null; gallerySize: number }
64	  | { type: "tap" }
65	  | { type: "camera_ready" }
66	  | { type: "frame_locked" }
67	  | { type: "server_result"; r: FaceEventResponse }
68	  | { type: "local_result"; r: FaceEventResponse }
69	  | { type: "challenge_advance" }
70	  | { type: "back_to_idle"; gallerySize: number }
71	  | { type: "error"; message: string };
72	
73	function reducer(state: GateState, action: Action): GateState {
74	  switch (action.type) {
75	    case "boot_complete":
76	      return { kind: "idle", lastSyncAt: action.cachedVersion, gallerySize: action.gallerySize };
77	    case "tap":
78	      return state.kind === "idle" ? { kind: "loading_camera" } : state;
79	    case "camera_ready":
80	      return state.kind === "loading_camera" ? { kind: "detecting" } : state;
81	    case "frame_locked":
82	      // The hook decides mode based on connectivity.
83	      return state.kind === "detecting"
84	        ? { kind: "matching", mode: navigator.onLine ? "server" : "local" }
85	        : state;
86	    case "server_result":
87	    case "local_result": {
88	      const r = action.r;
89	      if (r.challenge_required) {
90	        // Parsing poses defensively — server may add or change set.
91	        const poses = ["right", "up"];
92	        return { kind: "challenging", eventId: r.event_id, poses, poseIndex: 0 };
93	      }
94	      return {
95	        kind: "result",
96	        outcome: r.outcome,
97	        staffName: r.staff?.name ?? null,
98	        direction: r.direction ?? null,
99	        offline: action.type === "local_result",
100	      };
101	    }
102	    case "challenge_advance":
103	      if (state.kind !== "challenging") return state;
104	      return { ...state, poseIndex: state.poseIndex + 1 };
105	    case "back_to_idle":
106	      return { kind: "idle", lastSyncAt: new Date().toISOString(), gallerySize: action.gallerySize };
107	    case "error":
108	      return { kind: "error", message: action.message };
109	  }
110	}
111	
112	export interface UseGateMachine {
113	  state: GateState;
114	  videoRef: React.RefObject<HTMLVideoElement | null>;
115	  tap: () => void;
116	  serverConfig: ServerConfig | null;
117	  online: boolean;
118	}
119	
120	const DEFAULT_CONFIG: ServerConfig = {
121	  confidence_punch_threshold: 0.85,
122	  confidence_challenge_threshold: 0.65,
123	  confidence_reject_threshold: 0.5,
124	  random_challenge_probability: 0.07,
125	  duplicate_window_seconds: 60,
126	  collision_warning_threshold: 0.88,
127	};
128	
129	export function useGateMachine(): UseGateMachine {
130	  const [state, dispatch] = useReducer(reducer, { kind: "boot" } as GateState);
131	  const videoRef = useRef<HTMLVideoElement | null>(null);
132	  const streamRef = useRef<MediaStream | null>(null);
133	  const rafRef = useRef<number | null>(null);
134	  const lastTickRef = useRef<number>(performance.now());
135	  const dwellRef = useRef<number>(0);
136	  const inflightRef = useRef<boolean>(false);
137	  const stateRef = useRef<GateState>(state);
138	  const configRef = useRef<ServerConfig>(DEFAULT_CONFIG);
139	  const gallerySizeRef = useRef<number>(0);
140	  const onlineRef = useRef<boolean>(typeof navigator === "undefined" ? true : navigator.onLine);
141	
142	  useEffect(() => { stateRef.current = state; }, [state]);
143	
144	  // ── Boot: heartbeat + gallery sync ─────────────────────────────
145	  useEffect(() => {
146	    let cancelled = false;
147	    (async () => {
148	      try {
149	        const hb = await heartbeat();
150	        if (cancelled) return;
151	        if (hb.ok) {
152	          configRef.current = hb.data.config;
153	          const cachedVersion = await getCachedVersion();
154	          if (cachedVersion !== hb.data.gallery_version) {
155	            const galleryResp = await fetchGallery(cachedVersion);
156	            if (galleryResp.ok && galleryResp.status !== 304) {
157	              await replaceGallery(galleryResp.data.entries, galleryResp.data.gallery_version);
158	            }
159	          }
160	        }
161	        const size = await getGallerySize();
162	        gallerySizeRef.current = size;
163	        dispatch({ type: "boot_complete", cachedVersion: await getCachedVersion(), gallerySize: size });
164	        // Flush any pending offline punches.
165	        void flushOutbox();
166	      } catch (err) {
167	        // Boot offline — still allow gate to operate from cache.
168	        const size = await getGallerySize();
169	        gallerySizeRef.current = size;
170	        dispatch({ type: "boot_complete", cachedVersion: await getCachedVersion(), gallerySize: size });
171	      }
172	    })();
173	    return () => { cancelled = true; };
174	  }, []);
175	
176	  // ── Online/offline transitions: trigger reconcile ──────────────
177	  useEffect(() => {
178	    const onOnline = () => { onlineRef.current = true; void flushOutbox(); };
179	    const onOffline = () => { onlineRef.current = false; };
180	    window.addEventListener("online", onOnline);
181	    window.addEventListener("offline", onOffline);
182	    return () => {
183	      window.removeEventListener("online", onOnline);
184	      window.removeEventListener("offline", onOffline);
185	    };
186	  }, []);
187	
188	  // ── Camera lifecycle ───────────────────────────────────────────
189	  useEffect(() => {
190	    if (state.kind !== "loading_camera") return;
191	    let cancelled = false;
192	    (async () => {
193	      try {
194	        const stream = await navigator.mediaDevices.getUserMedia({
195	          video: { facingMode: "user", width: { ideal: 1280 }, height: { ideal: 720 } },
196	          audio: false,
197	        });
198	        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return; }
199	        streamRef.current = stream;
200	        if (videoRef.current) {
201	          videoRef.current.srcObject = stream;
202	          await videoRef.current.play().catch(() => {});
203	        }
204	        // Warm the face model in parallel.
205	        await getFaceLandmarker();
206	        dispatch({ type: "camera_ready" });
207	      } catch (err) {
208	        dispatch({ type: "error", message: errorMessage(err) });
209	      }
210	    })();
211	    return () => { cancelled = true; };
212	  }, [state.kind]);
213	
214	  // Stop camera when leaving detecting/matching/challenging.
215	  useEffect(() => {
216	    const k = state.kind;
217	    if (k === "idle" || k === "result" || k === "error" || k === "boot") {
218	      streamRef.current?.getTracks().forEach((t) => t.stop());
219	      streamRef.current = null;
220	      if (videoRef.current) videoRef.current.srcObject = null;
221	    }
222	  }, [state.kind]);
223	
224	  // ── Auto-return to idle after result ───────────────────────────
225	  useEffect(() => {
226	    if (state.kind !== "result") return;
227	    const t = setTimeout(() => {
228	      dispatch({ type: "back_to_idle", gallerySize: gallerySizeRef.current });
229	    }, RESULT_LINGER_MS);
230	    return () => clearTimeout(t);
231	  }, [state.kind]);
232	
233	  // ── Detect loop ────────────────────────────────────────────────
234	  useEffect(() => {
235	    if (state.kind !== "detecting") return;
236	    let stopped = false;
237	
238	    const loop = async () => {
239	      if (stopped) return;
240	      const now = performance.now();
241	      const dt = Math.max(1, now - lastTickRef.current);
242	      lastTickRef.current = now;
243	
244	      const video = videoRef.current;
245	      if (video && video.readyState >= 2 && !inflightRef.current) {
246	        try {
247	          const fl = await getFaceLandmarker();
248	          const result = fl.detectForVideo(video, now);
249	          const analysis = analyzeResult(result, video.videoWidth, video.videoHeight);
250	          const stable =
251	            analysis.hasSingleFace &&
252	            analysis.pose !== null &&
253	            Math.abs(analysis.pose.yaw) < 18 &&
254	            Math.abs(analysis.pose.pitch) < 18;
255	
256	          if (stable) {
257	            dwellRef.current += dt;
258	            if (dwellRef.current >= DETECT_DWELL_MS && analysis.bbox) {
259	              inflightRef.current = true;
260	              dwellRef.current = 0;
261	              dispatch({ type: "frame_locked" });
262	              try {
263	                const crop = cropFace(video, analysis.bbox);
264	                const embedding = await embed(crop);
265	                await matchAndDispatch(embedding);
266	              } catch (err) {
267	                dispatch({ type: "error", message: errorMessage(err) });
268	              } finally {
269	                inflightRef.current = false;
270	              }
271	            }
272	          } else {
273	            dwellRef.current = 0;
274	          }
275	        } catch (err) {
276	          console.warn("[gate detect] frame error", err);
277	        }
278	      }
279	      rafRef.current = requestAnimationFrame(loop);
280	    };
281	    rafRef.current = requestAnimationFrame(loop);
282	    return () => {
283	      stopped = true;
284	      if (rafRef.current) cancelAnimationFrame(rafRef.current);
285	    };
286	  }, [state.kind]);
287	
288	  // ── Server / local matching ────────────────────────────────────
289	  const matchAndDispatch = useCallback(async (embedding: number[]) => {
290	    const clientTimestamp = new Date().toISOString();
291	    if (onlineRef.current) {
292	      try {
293	        const res = await postFaceEvent({ embedding, client_timestamp: clientTimestamp });
294	        if (res.ok) {
295	          dispatch({ type: "server_result", r: res.data });
296	          return;
297	        }
298	        // Fall through to local match on server error.
299	      } catch {
300	        // Same — treat as offline.
301	      }
302	    }
303	    // Local fallback / offline path.
304	    const local = await localMatch(embedding);
305	    await enqueuePunch({
306	      id: cryptoRandomId(),
307	      embedding,
308	      client_timestamp: clientTimestamp,
309	      client_geo: null,
310	      local_match_staff_id: local?.staff_id ?? null,
311	      local_match_confidence: local?.similarity ?? null,
312	    });
313	    const outcome: GateOutcome = local && local.similarity >= configRef.current.confidence_punch_threshold
314	      ? "punched_offline_pending_verify"
315	      : "no_match";
316	    dispatch({
317	      type: "local_result",
318	      r: {
319	        outcome,
320	        event_id: "local-" + Date.now().toString(36),
321	        confidence: local?.similarity,
322	        staff: local ? { id: local.staff_id, name: null } : undefined,
323	      },
324	    });
325	  }, []);
326	
327	  const tap = useCallback(() => {
328	    if (stateRef.current.kind === "idle") dispatch({ type: "tap" });
329	  }, []);
330	
331	  return {
332	    state,
333	    videoRef,
334	    tap,
335	    serverConfig: configRef.current,
