/**
 * Gate state machine — the brain of the tablet.
 *
 * Owns:
 *  - camera lifecycle (active only while detecting/captured)
 *  - MediaPipe detect loop
 *  - ONNX embedding generation
 *  - online/offline routing (server match vs local fallback)
 *  - liveness challenge flow when the server asks for it
 *  - punch result UI state
 *  - outbox flush on reconnect + heartbeat-driven gallery refresh
 *
 * Server is source-of-truth. The tablet posts an embedding and
 * accepts whatever outcome the server returns. Offline events are
 * queued and re-verified against the server's current gallery on
 * reconnect.
 */

import { useCallback, useEffect, useReducer, useRef } from "react";

import {
  fetchGallery,
  flushOfflineBatch,
  heartbeat,
  postFaceEvent,
  type FaceEventResponse,
  type GateOutcome,
  type ServerConfig,
} from "../api/attendance";
import {
  getCachedGallery,
  getCachedVersion,
  getGallerySize,
  replaceGallery,
} from "../db/gallery";
import {
  enqueuePunch,
  listPending,
  markFailed,
  markSynced,
} from "../db/outbox";
import {
  analyzeResult,
  cropFace,
  getFaceLandmarker,
} from "./lib/faceLandmarker";
import { cosineSim, embed } from "./lib/embedder";

const DETECT_DWELL_MS = 350;
const RESULT_LINGER_MS = 2400;

export type GateState =
  | { kind: "boot" }
  | { kind: "idle"; lastSyncAt: string | null; gallerySize: number }
  | { kind: "loading_camera" }
  | { kind: "detecting" }
  | { kind: "matching"; mode: "server" | "local" }
  | { kind: "challenging"; eventId: string; poses: string[]; poseIndex: number }
  | { kind: "result"; outcome: GateOutcome; staffName: string | null; direction: "in" | "out" | null; offline: boolean }
  | { kind: "error"; message: string };

type Action =
  | { type: "boot_complete"; cachedVersion: string | null; gallerySize: number }
  | { type: "tap" }
  | { type: "camera_ready" }
  | { type: "frame_locked" }
  | { type: "server_result"; r: FaceEventResponse }
  | { type: "local_result"; r: FaceEventResponse }
  | { type: "challenge_advance" }
  | { type: "back_to_idle"; gallerySize: number }
  | { type: "error"; message: string };

function reducer(state: GateState, action: Action): GateState {
  switch (action.type) {
    case "boot_complete":
      return { kind: "idle", lastSyncAt: action.cachedVersion, gallerySize: action.gallerySize };
    case "tap":
      return state.kind === "idle" ? { kind: "loading_camera" } : state;
    case "camera_ready":
      return state.kind === "loading_camera" ? { kind: "detecting" } : state;
    case "frame_locked":
      // The hook decides mode based on connectivity.
      return state.kind === "detecting"
        ? { kind: "matching", mode: navigator.onLine ? "server" : "local" }
        : state;
    case "server_result":
    case "local_result": {
      const r = action.r;
      if (r.challenge_required) {
        // Parsing poses defensively — server may add or change set.
        const poses = ["right", "up"];
        return { kind: "challenging", eventId: r.event_id, poses, poseIndex: 0 };
      }
      return {
        kind: "result",
        outcome: r.outcome,
        staffName: r.staff?.name ?? null,
        direction: r.direction ?? null,
        offline: action.type === "local_result",
      };
    }
    case "challenge_advance":
      if (state.kind !== "challenging") return state;
      return { ...state, poseIndex: state.poseIndex + 1 };
    case "back_to_idle":
      return { kind: "idle", lastSyncAt: new Date().toISOString(), gallerySize: action.gallerySize };
    case "error":
      return { kind: "error", message: action.message };
  }
}

export interface UseGateMachine {
  state: GateState;
  videoRef: React.RefObject<HTMLVideoElement | null>;
  tap: () => void;
  serverConfig: ServerConfig | null;
  online: boolean;
}

const DEFAULT_CONFIG: ServerConfig = {
  confidence_punch_threshold: 0.85,
  confidence_challenge_threshold: 0.65,
  confidence_reject_threshold: 0.5,
  random_challenge_probability: 0.07,
  duplicate_window_seconds: 60,
  collision_warning_threshold: 0.88,
};

export function useGateMachine(): UseGateMachine {
  const [state, dispatch] = useReducer(reducer, { kind: "boot" } as GateState);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const rafRef = useRef<number | null>(null);
  const lastTickRef = useRef<number>(performance.now());
  const dwellRef = useRef<number>(0);
  const inflightRef = useRef<boolean>(false);
  const stateRef = useRef<GateState>(state);
  const configRef = useRef<ServerConfig>(DEFAULT_CONFIG);
  const gallerySizeRef = useRef<number>(0);
  const onlineRef = useRef<boolean>(typeof navigator === "undefined" ? true : navigator.onLine);

  useEffect(() => { stateRef.current = state; }, [state]);

  // ── Boot: heartbeat + gallery sync ─────────────────────────────
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const hb = await heartbeat();
        if (cancelled) return;
        if (hb.ok) {
          configRef.current = hb.data.config;
          const cachedVersion = await getCachedVersion();
          if (cachedVersion !== hb.data.gallery_version) {
            const galleryResp = await fetchGallery(cachedVersion);
            if (galleryResp.ok && galleryResp.status !== 304) {
              await replaceGallery(galleryResp.data.entries, galleryResp.data.gallery_version);
            }
          }
        }
        const size = await getGallerySize();
        gallerySizeRef.current = size;
        dispatch({ type: "boot_complete", cachedVersion: await getCachedVersion(), gallerySize: size });
        // Flush any pending offline punches.
        void flushOutbox();
      } catch (err) {
        // Boot offline — still allow gate to operate from cache.
        const size = await getGallerySize();
        gallerySizeRef.current = size;
        dispatch({ type: "boot_complete", cachedVersion: await getCachedVersion(), gallerySize: size });
      }
    })();
    return () => { cancelled = true; };
  }, []);

  // ── Online/offline transitions: trigger reconcile ──────────────
  useEffect(() => {
    const onOnline = () => { onlineRef.current = true; void flushOutbox(); };
    const onOffline = () => { onlineRef.current = false; };
    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);
    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  // ── Camera lifecycle ───────────────────────────────────────────
  useEffect(() => {
    if (state.kind !== "loading_camera") return;
    let cancelled = false;
    (async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false,
        });
        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return; }
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play().catch(() => {});
        }
        // Warm the face model in parallel.
        await getFaceLandmarker();
        dispatch({ type: "camera_ready" });
      } catch (err) {
        dispatch({ type: "error", message: errorMessage(err) });
      }
    })();
    return () => { cancelled = true; };
  }, [state.kind]);

  // Stop camera when leaving detecting/matching/challenging.
  useEffect(() => {
    const k = state.kind;
    if (k === "idle" || k === "result" || k === "error" || k === "boot") {
      streamRef.current?.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
      if (videoRef.current) videoRef.current.srcObject = null;
    }
  }, [state.kind]);

  // ── Auto-return to idle after result ───────────────────────────
  useEffect(() => {
    if (state.kind !== "result") return;
    const t = setTimeout(() => {
      dispatch({ type: "back_to_idle", gallerySize: gallerySizeRef.current });
    }, RESULT_LINGER_MS);
    return () => clearTimeout(t);
  }, [state.kind]);

  // ── Detect loop ────────────────────────────────────────────────
  useEffect(() => {
    if (state.kind !== "detecting") return;
    let stopped = false;

    const loop = async () => {
      if (stopped) return;
      const now = performance.now();
      const dt = Math.max(1, now - lastTickRef.current);
      lastTickRef.current = now;

      const video = videoRef.current;
      if (video && video.readyState >= 2 && !inflightRef.current) {
        try {
          const fl = await getFaceLandmarker();
          const result = fl.detectForVideo(video, now);
          const analysis = analyzeResult(result, video.videoWidth, video.videoHeight);
          const stable =
            analysis.hasSingleFace &&
            analysis.pose !== null &&
            Math.abs(analysis.pose.yaw) < 18 &&
            Math.abs(analysis.pose.pitch) < 18;

          if (stable) {
            dwellRef.current += dt;
            if (dwellRef.current >= DETECT_DWELL_MS && analysis.bbox) {
              inflightRef.current = true;
              dwellRef.current = 0;
              dispatch({ type: "frame_locked" });
              try {
                const crop = cropFace(video, analysis.bbox);
                const embedding = await embed(crop);
                await matchAndDispatch(embedding);
              } catch (err) {
                dispatch({ type: "error", message: errorMessage(err) });
              } finally {
                inflightRef.current = false;
              }
            }
          } else {
            dwellRef.current = 0;
          }
        } catch (err) {
          console.warn("[gate detect] frame error", err);
        }
      }
      rafRef.current = requestAnimationFrame(loop);
    };
    rafRef.current = requestAnimationFrame(loop);
    return () => {
      stopped = true;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [state.kind]);

  // ── Server / local matching ────────────────────────────────────
  const matchAndDispatch = useCallback(async (embedding: number[]) => {
    const clientTimestamp = new Date().toISOString();
    if (onlineRef.current) {
      try {
        const res = await postFaceEvent({ embedding, client_timestamp: clientTimestamp });
        if (res.ok) {
          dispatch({ type: "server_result", r: res.data });
          return;
        }
        // Fall through to local match on server error.
      } catch {
        // Same — treat as offline.
      }
    }
    // Local fallback / offline path.
    const local = await localMatch(embedding);
    await enqueuePunch({
      id: cryptoRandomId(),
      embedding,
      client_timestamp: clientTimestamp,
      client_geo: null,
      local_match_staff_id: local?.staff_id ?? null,
      local_match_confidence: local?.similarity ?? null,
    });
    const outcome: GateOutcome = local && local.similarity >= configRef.current.confidence_punch_threshold
      ? "punched_offline_pending_verify"
      : "no_match";
    dispatch({
      type: "local_result",
      r: {
        outcome,
        event_id: "local-" + Date.now().toString(36),
        confidence: local?.similarity,
        staff: local ? { id: local.staff_id, name: null } : undefined,
      },
    });
  }, []);

  const tap = useCallback(() => {
    if (stateRef.current.kind === "idle") dispatch({ type: "tap" });
  }, []);

  return {
    state,
    videoRef,
    tap,
    serverConfig: configRef.current,
    online: onlineRef.current,
  };
}

// ── Helpers ───────────────────────────────────────────────────────

async function localMatch(embedding: number[]): Promise<{ staff_id: string; similarity: number } | null> {
  const gallery = await getCachedGallery();
  if (gallery.length === 0) return null;
  let best: { staff_id: string; similarity: number } | null = null;
  for (const row of gallery) {
    const sim = cosineSim(embedding, row.embedding);
    if (!best || sim > best.similarity) best = { staff_id: row.staff_id, similarity: sim };
  }
  return best;
}

async function flushOutbox(): Promise<void> {
  if (!navigator.onLine) return;
  const pending = await listPending();
  if (pending.length === 0) return;
  try {
    const res = await flushOfflineBatch(
      pending.map((p) => ({
        client_event_id: p.id,
        embedding: p.embedding,
        client_timestamp: p.client_timestamp,
        client_geo: p.client_geo,
      })),
    );
    if (!res.ok) return;
    const succeededIds = res.data.results
      .filter((r) => "outcome" in r && !("error" in r))
      .map((r) => r.client_event_id)
      .filter((v): v is string => !!v);
    if (succeededIds.length > 0) await markSynced(succeededIds);
  } catch (err) {
    for (const p of pending) await markFailed(p.id, errorMessage(err));
  }
}

function cryptoRandomId(): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) return crypto.randomUUID();
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}

function errorMessage(err: unknown): string {
  if (err instanceof Error) return err.message;
  if (typeof err === "string") return err;
  return "Unknown error";
}

