  id: 'attendance',
  titleKey: 'attendance',
  subtitleKey: 'attendanceSub',
  glyph: '🪪',
  entryRoute: 'AttendanceGate',
  requiredPermissions: ['attendance.view'],
  screens: [{ name: 'AttendanceGate', component: GateScreen }],
};

