/**
 * Attendance Plugin — Database Layer
 *
 * Backs the face check-in gate. Owns CRUD over the face gallery
 * (`attendance_face_gallery`), the raw event stream (`attendance_events`),
 * and the in/out session mirror in the shared `staff_attendance` table so
 * existing "who's in" surfaces keep working.
 *
 * Schema DDL lives in `lib/postgres-schema.ts` via
 * `ensureOfficeOpsPostgresSchema()` — this file is CRUD only.
 *
 * Embeddings are L2-normalized 192-float vectors, stored as JSON text.
 * Treat them like fingerprints: never log the raw vector.
 */

import { randomUUID } from "crypto";

import { getDb } from "../../lib/database";
import { ensureOfficeOpsPostgresSchema } from "../../lib/postgres";

export async function initAttendanceSchema(): Promise<void> {
  await ensureOfficeOpsPostgresSchema();
}

export type GalleryEntry = {
  staff_id: string;
  name: string | null;
  embedding: number[];
};

export type StaffRow = {
  id: string;
  name: string;
  is_active: number;
};

export type AttendanceEventInput = {
  siteId: string;
  staffId: string | null;
  sessionId: string | null;
  direction: "in" | "out" | null;
  outcome: string;
  confidence: number | null;
  clientEventId: string | null;
  clientTimestamp: string | null;
  geo: {
    latitude: number | null;
    longitude: number | null;
    accuracy: number | null;
    mocked: boolean;
  } | null;
  geoFlagged: boolean;
  deviceId: string | null;
  guardId: string | null;
  source: "gate" | "offline_batch";
};

// ── Gallery ────────────────────────────────────────────────────────

/** Active enrolled face vectors for a site, joined to staff names. */
export async function listGallery(siteId: string): Promise<GalleryEntry[]> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT g.staff_id, s.name, g.embedding
      FROM attendance_face_gallery g
      JOIN staff s ON s.id = g.staff_id
      WHERE g.is_active = 1
        AND s.is_active = 1
        AND (g.site_id = ? OR g.site_id IS NULL)
      ORDER BY g.updated_at ASC
    `,
    args: [siteId],
  });
  return (result.rows as Array<{ staff_id: string; name: string | null; embedding: string }>)
    .map((r) => ({
      staff_id: r.staff_id,
      name: r.name,
      embedding: safeParseEmbedding(r.embedding),
    }))
    .filter((e) => e.embedding.length > 0);
}

/**
 * Gallery version = the latest `updated_at` across active rows for the site.
 * The gate caches by this string and only re-pulls when it changes.
 */
export async function getGalleryVersion(siteId: string): Promise<string> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT COALESCE(MAX(updated_at), 'empty') AS version, COUNT(*) AS n
      FROM attendance_face_gallery
      WHERE is_active = 1 AND (site_id = ? OR site_id IS NULL)
    `,
    args: [siteId],
  });
  const row = result.rows[0] as { version: string; n: number } | undefined;
  if (!row) return "empty";
  return `${row.version}:${row.n}`;
}

/** Enroll (or re-enroll) a face sample for a staff member. */
export async function insertGalleryEntry(input: {
  staffId: string;
  siteId: string | null;
  embedding: number[];
  quality: number | null;
  enrolledBy: string | null;
}): Promise<string> {
  const db = await getDb();
  const id = randomUUID();
  await db.execute({
    sql: `
      INSERT INTO attendance_face_gallery
        (id, staff_id, site_id, embedding, embedding_dim, quality, enrolled_by)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `,
    args: [
      id,
      input.staffId,
      input.siteId,
      JSON.stringify(input.embedding),
      input.embedding.length,
      input.quality,
      input.enrolledBy,
    ],
  });
  return id;
}

// ── Events + session mirror ────────────────────────────────────────

export async function getStaffById(staffId: string): Promise<StaffRow | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT id, name, is_active FROM staff WHERE id = ? LIMIT 1`,
    args: [staffId],
  });
  return (result.rows[0] as StaffRow | undefined) ?? null;
}

/** Whether an event with this idempotency key already landed. */
export async function findEventByClientId(
  clientEventId: string,
): Promise<{ id: string; outcome: string; direction: string | null } | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT id, outcome, direction FROM attendance_events WHERE client_event_id = ? LIMIT 1`,
    args: [clientEventId],
  });
  return (
    (result.rows[0] as { id: string; outcome: string; direction: string | null } | undefined) ??
    null
  );
}

/** Most recent event for a staff member, for the dedupe window check. */
export async function getLastEventForStaff(
  staffId: string,
): Promise<{ created_at: string; direction: string | null } | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT created_at, direction FROM attendance_events
      WHERE staff_id = ? ORDER BY created_at DESC LIMIT 1
    `,
    args: [staffId],
  });
  return (
    (result.rows[0] as { created_at: string; direction: string | null } | undefined) ?? null
  );
}

/** Open staff_attendance session (checked in, not yet out), if any. */
export async function getOpenSession(staffId: string): Promise<{ id: string } | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT id FROM staff_attendance
      WHERE staff_id = ? AND marked_out_at IS NULL
      ORDER BY marked_in_at DESC LIMIT 1
    `,
    args: [staffId],
  });
  return (result.rows[0] as { id: string } | undefined) ?? null;
}

/** Open a new attendance session (check-in). Returns the session id. */
export async function openSession(
  staffId: string,
  guardId: string | null,
  guardName: string | null,
): Promise<string> {
  const db = await getDb();
  const id = randomUUID();
  await db.execute({
    sql: `
      INSERT INTO staff_attendance (id, staff_id, marked_in_by_guard_id, marked_in_by_guard_name)
      VALUES (?, ?, ?, ?)
    `,
    args: [id, staffId, guardId, guardName],
  });
  return id;
}

/** Close an open session (check-out). */
export async function closeSession(
  sessionId: string,
  guardId: string | null,
  guardName: string | null,
): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      UPDATE staff_attendance
      SET marked_out_at = now()::text,
          marked_out_by_guard_id = ?,
          marked_out_by_guard_name = ?,
          updated_at = now()::text
      WHERE id = ?
    `,
    args: [guardId, guardName, sessionId],
  });
}

export async function insertAttendanceEvent(input: AttendanceEventInput): Promise<string> {
  const db = await getDb();
  const id = randomUUID();
  await db.execute({
    sql: `
      INSERT INTO attendance_events
        (id, site_id, staff_id, session_id, direction, outcome, confidence,
         client_event_id, client_timestamp, geo_lat, geo_lng, geo_accuracy,
         geo_mocked, geo_flagged, device_id, guard_id, source)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `,
    args: [
      id,
      input.siteId,
      input.staffId,
      input.sessionId,
      input.direction,
      input.outcome,
      input.confidence,
      input.clientEventId,
      input.clientTimestamp,
      input.geo?.latitude ?? null,
      input.geo?.longitude ?? null,
      input.geo?.accuracy ?? null,
      input.geo?.mocked ? 1 : 0,
      input.geoFlagged ? 1 : 0,
      input.deviceId,
      input.guardId,
      input.source,
    ],
  });
  return id;
}

// ── helpers ────────────────────────────────────────────────────────

function safeParseEmbedding(raw: string): number[] {
  try {
    const v = JSON.parse(raw);
    if (Array.isArray(v) && v.every((x) => typeof x === "number")) return v as number[];
  } catch {
    /* ignore malformed rows */
  }
  return [];
}

