export async function insertGalleryEntry(input: {
  staffId: string;
  siteId: string | null;
  embedding: number[];
  quality: number | null;
  enrolledBy: string | null;
}): Promise<string> {
  const db = await getDb();
  const id = randomUUID();
  await db.execute({
    sql: `
      INSERT INTO attendance_face_gallery
        (id, staff_id, site_id, embedding, embedding_dim, quality, enrolled_by)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `,
    args: [
      id,
      input.staffId,
      input.siteId,
      JSON.stringify(input.embedding),
      input.embedding.length,
      input.quality,
      input.enrolledBy,
    ],
  });
  return id;
}

// ── Events + session mirror ────────────────────────────────────────

export async function getStaffById(staffId: string): Promise<StaffRow | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT id, name, is_active FROM staff WHERE id = ? LIMIT 1`,
    args: [staffId],
  });
  return (result.rows[0] as StaffRow | undefined) ?? null;
}

/** Whether an event with this idempotency key already landed. */
export async function findEventByClientId(
  clientEventId: string,
): Promise<{ id: string; outcome: string; direction: string | null } | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `SELECT id, outcome, direction FROM attendance_events WHERE client_event_id = ? LIMIT 1`,
    args: [clientEventId],
  });
  return (
    (result.rows[0] as { id: string; outcome: string; direction: string | null } | undefined) ??
    null
  );
}

/** Most recent event for a staff member, for the dedupe window check. */
export async function getLastEventForStaff(
  staffId: string,
): Promise<{ created_at: string; direction: string | null } | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT created_at, direction FROM attendance_events
      WHERE staff_id = ? ORDER BY created_at DESC LIMIT 1
    `,
    args: [staffId],
  });
  return (
    (result.rows[0] as { created_at: string; direction: string | null } | undefined) ?? null
  );
}

/** Open staff_attendance session (checked in, not yet out), if any. */
export async function getOpenSession(staffId: string): Promise<{ id: string } | null> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      SELECT id FROM staff_attendance
      WHERE staff_id = ? AND marked_out_at IS NULL
      ORDER BY marked_in_at DESC LIMIT 1
    `,
    args: [staffId],
  });
  return (result.rows[0] as { id: string } | undefined) ?? null;
}

/** Open a new attendance session (check-in). Returns the session id. */
export async function openSession(
  staffId: string,
  guardId: string | null,
  guardName: string | null,
): Promise<string> {
  const db = await getDb();
  const id = randomUUID();
  await db.execute({
    sql: `
      INSERT INTO staff_attendance (id, staff_id, marked_in_by_guard_id, marked_in_by_guard_name)
      VALUES (?, ?, ?, ?)
    `,
    args: [id, staffId, guardId, guardName],
  });
  return id;
}

/** Close an open session (check-out). */
export async function closeSession(
  sessionId: string,
  guardId: string | null,
  guardName: string | null,
): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      UPDATE staff_attendance
      SET marked_out_at = now()::text,
          marked_out_by_guard_id = ?,
          marked_out_by_guard_name = ?,
          updated_at = now()::text
      WHERE id = ?
    `,
    args: [guardId, guardName, sessionId],
  });
}

export async function insertAttendanceEvent(input: AttendanceEventInput): Promise<string> {
  const db = await getDb();
  const id = randomUUID();
  await db.execute({
    sql: `
      INSERT INTO attendance_events
        (id, site_id, staff_id, session_id, direction, outcome, confidence,
         client_event_id, client_timestamp, geo_lat, geo_lng, geo_accuracy,
         geo_mocked, geo_flagged, device_id, guard_id, source)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `,
    args: [
      id,
      input.siteId,
      input.staffId,
      input.sessionId,
      input.direction,
      input.outcome,
      input.confidence,
      input.clientEventId,
      input.clientTimestamp,
      input.geo?.latitude ?? null,
      input.geo?.longitude ?? null,
      input.geo?.accuracy ?? null,
      input.geo?.mocked ? 1 : 0,
      input.geoFlagged ? 1 : 0,
      input.deviceId,
      input.guardId,
      input.source,
    ],
  });
  return id;
}

// ── helpers ────────────────────────────────────────────────────────

function safeParseEmbedding(raw: string): number[] {
  try {
    const v = JSON.parse(raw);
    if (Array.isArray(v) && v.every((x) => typeof x === "number")) return v as number[];
  } catch {
    /* ignore malformed rows */
  }
  return [];
}

