/**
 * Attendance matching — pure functions. Server is source of truth for
 * identity: the gate sends a vector, this decides who it is.
 *
 * Policy (thresholds, dedupe window, geofence radius) lives here, not in the
 * app. Move to per-site settings later; the shape is already config-driven.
 */

import type { GalleryEntry } from "./db";

export type AttendanceConfig = {
  confidence_punch_threshold: number;
  confidence_challenge_threshold: number;
  confidence_reject_threshold: number;
  duplicate_window_seconds: number;
  geofence_radius_meters: number | null;
};

export const DEFAULT_ATTENDANCE_CONFIG: AttendanceConfig = {
  confidence_punch_threshold: 0.85,
  confidence_challenge_threshold: 0.65,
  confidence_reject_threshold: 0.5,
  duplicate_window_seconds: 60,
  geofence_radius_meters: null,
};

/** Cosine similarity between two L2-normalized vectors (== dot product). */
export function cosineSim(a: number[], b: number[]): number {
  if (a.length !== b.length || a.length === 0) return -1;
  let dot = 0;
  for (let i = 0; i < a.length; i++) dot += a[i] * b[i];
  return dot;
}

export type Match = { staffId: string; name: string | null; similarity: number };

/** Best gallery match for an embedding, or null on an empty gallery. */
export function matchEmbedding(embedding: number[], gallery: GalleryEntry[]): Match | null {
  let best: Match | null = null;
  for (const entry of gallery) {
    const similarity = cosineSim(embedding, entry.embedding);
    if (!best || similarity > best.similarity) {
      best = { staffId: entry.staff_id, name: entry.name, similarity };
    }
  }
  return best;
}

