/**
 * Attendance punch service — the single orchestration point for turning a
 * face embedding into a punch. Reused by both the live gate endpoint and the
 * offline-batch reconciler so the two paths can never drift.
 *
 * Automation-surface readiness: this is one function with a typed param
 * object and a single decision point. When attendance gets a flow-pack, the
 * `staff.attendance_changed` event (already reserved in trigger-definitions)
 * is a one-line emit at the marked ── return below.
 */

import {
  findEventByClientId,
  getLastEventForStaff,
  getOpenSession,
  getStaffById,
  insertAttendanceEvent,
  openSession,
  closeSession,
  type GalleryEntry,
} from "./db";
import {
  matchEmbedding,
  type AttendanceConfig,
} from "./matcher";

export type PunchGeo = {
  latitude: number | null;
  longitude: number | null;
  accuracy: number | null;
  mocked: boolean;
} | null;

export type ProcessFaceEventParams = {
  siteId: string;
  guardId: string | null;
  guardName: string | null;
  deviceId: string | null;
  embedding: number[];
  clientEventId: string | null;
  clientTimestamp: string | null;
  geo: PunchGeo;
  source: "gate" | "offline_batch";
  gallery: GalleryEntry[];
  config: AttendanceConfig;
};

export type FaceEventOutcome = {
  outcome:
    | "checked_in"
    | "checked_out"
    | "duplicate"
    | "low_confidence"
    | "no_match";
  event_id: string;
  confidence: number | null;
  direction: "in" | "out" | null;
  staff: { id: string; name: string | null } | null;
  geo_flagged: boolean;
};

export async function processFaceEvent(
  params: ProcessFaceEventParams,
): Promise<FaceEventOutcome> {
  const { config } = params;

  // Idempotency: an offline event replayed twice resolves to its first result.
  if (params.clientEventId) {
    const existing = await findEventByClientId(params.clientEventId);
    if (existing) {
      return {
        outcome: normalizeOutcome(existing.outcome),
        event_id: existing.id,
        confidence: null,
        direction: (existing.direction as "in" | "out" | null) ?? null,
        staff: null,
        geo_flagged: false,
      };
    }
  }

  // Mock location is a soft anomaly flag, never a hard block (mirrors the
  // offline-first dispense stance): record it, let the dashboard surface it.
  const geoFlagged = params.geo?.mocked === true;

  const match = matchEmbedding(params.embedding, params.gallery);

  // ── No match / below reject floor ────────────────────────────────
  if (!match || match.similarity < config.confidence_reject_threshold) {
    const eventId = await insertAttendanceEvent({
      ...eventBase(params),
      staffId: null,
      sessionId: null,
      direction: null,
      outcome: "no_match",
      confidence: match ? match.similarity : null,
      geoFlagged,
    });
    return {
      outcome: "no_match",
      event_id: eventId,
      confidence: match ? match.similarity : null,
      direction: null,
      staff: null,
      geo_flagged: geoFlagged,
    };
  }

  // ── Low confidence: a candidate, but under the punch bar → ask retry ─
  if (match.similarity < config.confidence_punch_threshold) {
    const eventId = await insertAttendanceEvent({
      ...eventBase(params),
      staffId: match.staffId,
      sessionId: null,
      direction: null,
      outcome: "low_confidence",
      confidence: match.similarity,
      geoFlagged,
    });
    return {
      outcome: "low_confidence",
      event_id: eventId,
      confidence: match.similarity,
      direction: null,
      staff: null,
      geo_flagged: geoFlagged,
    };
  }

  // ── Confident match ──────────────────────────────────────────────
  const staff = await getStaffById(match.staffId);
  if (!staff || staff.is_active !== 1) {
    const eventId = await insertAttendanceEvent({
      ...eventBase(params),
      staffId: match.staffId,
      sessionId: null,
      direction: null,
      outcome: "no_match",
      confidence: match.similarity,
      geoFlagged,
    });
    return {
      outcome: "no_match",
      event_id: eventId,
      confidence: match.similarity,
      direction: null,
      staff: null,
      geo_flagged: geoFlagged,
    };
  }

  // Dedupe: a second confident read within the window is not a new toggle.
  const last = await getLastEventForStaff(match.staffId);
  if (last && withinWindow(last.created_at, config.duplicate_window_seconds)) {
    const eventId = await insertAttendanceEvent({
      ...eventBase(params),
      staffId: match.staffId,
      sessionId: null,
      direction: (last.direction as "in" | "out" | null) ?? null,
      outcome: "duplicate",
      confidence: match.similarity,
      geoFlagged,
    });
    return {
      outcome: "duplicate",
      event_id: eventId,
      confidence: match.similarity,
      direction: (last.direction as "in" | "out" | null) ?? null,
      staff: { id: staff.id, name: staff.name },
      geo_flagged: geoFlagged,
    };
  }

  // Toggle in/out off the open session.
  const open = await getOpenSession(match.staffId);
  let direction: "in" | "out";
  let sessionId: string;
  let outcome: "checked_in" | "checked_out";
  if (open) {
    await closeSession(open.id, params.guardId, params.guardName);
    direction = "out";
    sessionId = open.id;
    outcome = "checked_out";
  } else {
    sessionId = await openSession(match.staffId, params.guardId, params.guardName);
    direction = "in";
    outcome = "checked_in";
  }

  const eventId = await insertAttendanceEvent({
    ...eventBase(params),
    staffId: match.staffId,
    sessionId,
    direction,
    outcome,
    confidence: match.similarity,
    geoFlagged,
  });

  // NOTE: single emit point for the future flow-pack:
  //   runFlowRules("attendance", "staff.attendance_changed", { staffId, direction })
  return {
    outcome,
    event_id: eventId,
    confidence: match.similarity,
    direction,
    staff: { id: staff.id, name: staff.name },
    geo_flagged: geoFlagged,
  };
}

function eventBase(params: ProcessFaceEventParams) {
  return {
    siteId: params.siteId,
    clientEventId: params.clientEventId,
    clientTimestamp: params.clientTimestamp,
    geo: params.geo,
    deviceId: params.deviceId,
    guardId: params.guardId,
    source: params.source,
  };
}

function withinWindow(createdAt: string, windowSeconds: number): boolean {
  const t = Date.parse(createdAt);
  if (Number.isNaN(t)) return false;
  return Date.now() - t < windowSeconds * 1000;
}

function normalizeOutcome(raw: string): FaceEventOutcome["outcome"] {
  switch (raw) {
    case "checked_in":
    case "checked_out":
    case "duplicate":
    case "low_confidence":
    case "no_match":
      return raw;
    default:
      return "no_match";
  }
}

