/**
 * Attendance Plugin — HTTP Routes
 *
 * Face check-in gate surface under /api/attendance/*.
 *
 *   GET  /api/attendance/heartbeat            — server time, gallery version, config
 *   GET  /api/attendance/embeddings/gallery   — enrolled face vectors (versioned)
 *   POST /api/attendance/face-events          — submit a face event → punch outcome
 *   POST /api/attendance/face-events/offline-batch — flush queued offline events
 *   POST /api/attendance/enroll               — admin: enroll a staff face sample
 *
 * Auth reuses the visitor guard session (x-guard-token + x-site-id), same as
 * the inventory module — the field-app is already guard-authenticated. Enroll
 * additionally accepts the admin Bearer token (ops-dashboard).
 *
 * Server is source of truth: matching/thresholds/dedupe all run here. The app
 * only sends a 192-float vector; no policy lives on the device.
 */

import type { IncomingMessage, ServerResponse } from "http";
import { parse as parseUrl } from "url";

import { logError } from "../../lib/logger";
import { validateGuardSession } from "../visitor/guard-auth";
import { resolveAdminSession } from "../visitor/admin-auth";
import { getGalleryVersion, insertGalleryEntry, listGallery } from "./db";
import { DEFAULT_ATTENDANCE_CONFIG } from "./matcher";
import { processFaceEvent, type PunchGeo } from "./service";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
  "Access-Control-Allow-Headers":
    "Content-Type,Accept,Authorization,x-guard-token,x-site-id,x-device-id",
};

const MAX_EMBEDDING_DIM = 1024;
const MAX_BATCH = 200;

function json(res: ServerResponse, status: number, data: unknown): void {
  res.writeHead(status, { "Content-Type": "application/json", ...CORS_HEADERS });
  res.end(JSON.stringify(data));
}

function corsPreflight(res: ServerResponse): void {
  res.writeHead(204, { ...CORS_HEADERS, "Access-Control-Max-Age": "86400" });
  res.end();
}

function header(req: IncomingMessage, name: string): string | undefined {
  const v = req.headers[name];
  return Array.isArray(v) ? v[0] : v;
}

async function readBodyJson(req: IncomingMessage): Promise<Record<string, unknown>> {
  return new Promise((resolve) => {
    let raw = "";
    req.on("data", (chunk) => {
      raw += chunk;
    });
    req.on("end", () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch {
        resolve({});
      }
    });
    req.on("error", () => resolve({}));
  });
}

type AuthedRequest = {
  guardId: string;
  guardName: string;
  siteId: string;
  deviceId: string | null;
  isAdmin: boolean;
};

async function authenticate(
  req: IncomingMessage,
  res: ServerResponse,
  { allowAdmin = false }: { allowAdmin?: boolean } = {},
): Promise<AuthedRequest | null> {
  const token = header(req, "x-guard-token");
  if (token) {
    const session = await validateGuardSession(token);
    if (!session) {
      json(res, 401, { error: "Invalid or expired session" });
      return null;
    }
    const siteId = header(req, "x-site-id");
    if (!siteId) {
      json(res, 400, { error: "Missing x-site-id" });
      return null;
    }
    return {
      guardId: session.guardId,
      guardName: session.guardName,
      siteId,
      deviceId: header(req, "x-device-id") ?? null,
      isAdmin: false,
    };
  }

  if (allowAdmin) {
    const admin = await resolveAdminSession(req);
    if (admin) {
      const siteId = header(req, "x-site-id");
      if (!siteId) {
        json(res, 400, { error: "Missing x-site-id" });
        return null;
      }
      return {
        guardId: `admin:${admin.email}`,
        guardName: admin.name,
        siteId,
        deviceId: header(req, "x-device-id") ?? null,
        isAdmin: true,
      };
    }
  }

  json(res, 401, { error: "Missing x-guard-token" });
  return null;
}

/** Parse and sanity-check an embedding array from an untrusted body. */
function parseEmbedding(v: unknown): number[] | null {
  if (!Array.isArray(v)) return null;
  if (v.length === 0 || v.length > MAX_EMBEDDING_DIM) return null;
  const out: number[] = [];
  for (const x of v) {
    if (typeof x !== "number" || !Number.isFinite(x)) return null;
    out.push(x);
  }
  return out;
}

function parseGeo(v: unknown): PunchGeo {
  if (!v || typeof v !== "object") return null;
  const g = v as Record<string, unknown>;
  const num = (x: unknown): number | null =>
    typeof x === "number" && Number.isFinite(x) ? x : null;
  const lat = num(g.latitude);
  const lng = num(g.longitude);
  if (lat === null && lng === null && g.mocked === undefined) return null;
  return {
    latitude: lat,
    longitude: lng,
    accuracy: num(g.accuracy),
    mocked: g.mocked === true,
  };
}

function clientConfig() {
  const c = DEFAULT_ATTENDANCE_CONFIG;
  return {
    confidence_punch_threshold: c.confidence_punch_threshold,
    confidence_challenge_threshold: c.confidence_challenge_threshold,
    confidence_reject_threshold: c.confidence_reject_threshold,
    duplicate_window_seconds: c.duplicate_window_seconds,
    geofence_radius_meters: c.geofence_radius_meters,
