export async function handleAttendanceRequest(
  req: IncomingMessage,
  res: ServerResponse,
): Promise<boolean> {
  const { pathname } = parseUrl(req.url ?? "", true);
  const method = req.method ?? "GET";

  if (!pathname || !pathname.startsWith("/api/attendance/")) return false;

  if (method === "OPTIONS") {
    corsPreflight(res);
    return true;
  }

  try {
    return await dispatch(req, res, pathname, method);
  } catch (error) {
    logError("attendance-routes", {
      action: `${method} ${pathname}`,
      error: error instanceof Error ? error.message : String(error),
    });
    if (res.headersSent) return true;
    json(res, 500, { error: "Attendance request failed" });
    return true;
  }
}

async function dispatch(
  req: IncomingMessage,
  res: ServerResponse,
  pathname: string,
  method: string,
): Promise<boolean> {
  // ── Heartbeat ──────────────────────────────────────────────────
  if (pathname === "/api/attendance/heartbeat" && method === "GET") {
    const auth = await authenticate(req, res);
    if (!auth) return true;
    json(res, 200, {
      server_time: new Date().toISOString(),
      gallery_version: await getGalleryVersion(auth.siteId),
      config: clientConfig(),
    });
    return true;
  }

  // ── Gallery ────────────────────────────────────────────────────
  if (pathname === "/api/attendance/embeddings/gallery" && method === "GET") {
    const auth = await authenticate(req, res);
    if (!auth) return true;
    const version = await getGalleryVersion(auth.siteId);
    const since = parseUrl(req.url ?? "", true).query["since"] as string | undefined;
    if (since && since === version) {
      json(res, 200, { gallery_version: version, unchanged: true, entries: [] });
      return true;
    }
    const entries = await listGallery(auth.siteId);
    json(res, 200, { gallery_version: version, unchanged: false, entries });
    return true;
  }

  // ── Single face event ──────────────────────────────────────────
  if (pathname === "/api/attendance/face-events" && method === "POST") {
    const auth = await authenticate(req, res);
    if (!auth) return true;
    const body = await readBodyJson(req);
    const embedding = parseEmbedding(body.embedding);
    if (!embedding) {
      json(res, 400, { error: "Invalid or missing embedding" });
      return true;
    }
    const gallery = await listGallery(auth.siteId);
    const outcome = await processFaceEvent({
      siteId: auth.siteId,
      guardId: auth.guardId,
      guardName: auth.guardName,
      deviceId: auth.deviceId,
      embedding,
      clientEventId: typeof body.client_event_id === "string" ? body.client_event_id : null,
      clientTimestamp: typeof body.client_timestamp === "string" ? body.client_timestamp : null,
      geo: parseGeo(body.geo ?? body.client_geo),
      source: "gate",
      gallery,
      config: DEFAULT_ATTENDANCE_CONFIG,
    });
    json(res, 200, outcome);
    return true;
  }

  // ── Offline batch flush ────────────────────────────────────────
  if (pathname === "/api/attendance/face-events/offline-batch" && method === "POST") {
    const auth = await authenticate(req, res);
    if (!auth) return true;
    const body = await readBodyJson(req);
    const events = Array.isArray(body.events) ? body.events : null;
    if (!events) {
      json(res, 400, { error: "Missing events array" });
      return true;
    }
    if (events.length > MAX_BATCH) {
      json(res, 413, { error: `Batch too large (max ${MAX_BATCH})` });
      return true;
    }
    // Load the gallery once for the whole batch.
    const gallery = await listGallery(auth.siteId);
    const results: Array<Record<string, unknown>> = [];
    for (const raw of events) {
      const ev = (raw ?? {}) as Record<string, unknown>;
      const clientEventId = typeof ev.client_event_id === "string" ? ev.client_event_id : null;
      const embedding = parseEmbedding(ev.embedding);
      if (!embedding) {
        results.push({ client_event_id: clientEventId, error: "invalid_embedding" });
        continue;
      }
      try {
        const outcome = await processFaceEvent({
          siteId: auth.siteId,
          guardId: auth.guardId,
          guardName: auth.guardName,
          deviceId: auth.deviceId,
          embedding,
          clientEventId,
          clientTimestamp: typeof ev.client_timestamp === "string" ? ev.client_timestamp : null,
          geo: parseGeo(ev.geo ?? ev.client_geo),
          source: "offline_batch",
          gallery,
          config: DEFAULT_ATTENDANCE_CONFIG,
        });
        results.push({ client_event_id: clientEventId, ...outcome });
      } catch (err) {
        results.push({
          client_event_id: clientEventId,
          error: err instanceof Error ? err.message : "failed",
        });
      }
    }
    json(res, 200, { results });
    return true;
  }

  // ── Enroll (admin or guard) ────────────────────────────────────
  if (pathname === "/api/attendance/enroll" && method === "POST") {
    const auth = await authenticate(req, res, { allowAdmin: true });
    if (!auth) return true;
    const body = await readBodyJson(req);
    const staffId = typeof body.staff_id === "string" ? body.staff_id : null;
    const embedding = parseEmbedding(body.embedding);
    if (!staffId || !embedding) {
      json(res, 400, { error: "Missing staff_id or embedding" });
      return true;
    }
    const id = await insertGalleryEntry({
      staffId,
      siteId: auth.siteId,
      embedding,
      quality: typeof body.quality === "number" ? body.quality : null,
      enrolledBy: auth.guardId,
    });
    json(res, 200, { ok: true, id, gallery_version: await getGalleryVersion(auth.siteId) });
    return true;
  }

  json(res, 404, { error: "Unknown attendance route" });
  return true;
}

